public void MyLoggingEventHandler (Object sender, LoggingUtilityEventArgs args)
{
	// Event handler is called once for each log entry.
	// args.EventData contains the log entry data (TimeStamp, Type, Priority,
	// MainText, AdditionalText, Link).
}

